INSERT INTO entity_ots_component SELECT 'acme', concat('cmp_', toString(number)),
 if(number < 300, NULL, if(number % 2 = 0, 'Passives/Capacitors', 'Actives')),
 if(number < 120, 'inactive', 'active'),
 [tuple(concat('spec_', toString(number)), if(number % 3 = 0, NULL, 'MPN'), NULL, 'description', NULL, NULL)],
 if(number < 400, [], [if(number = 450, 'orphan_part', concat('part_', toString(if(number >= 400 AND number < 450, 400 + intDiv(toInt64(number) - 400, 2), toInt64(number)))))]),
 toUInt64(if(number < 400, 0, 1)), toDateTime64('2026-04-27 00:00:00', 3, 'UTC')
 FROM numbers(2000);

INSERT INTO entity_off_the_shelf_part SELECT 'acme', concat('part_', toString(number)),
 concat('manufacturer_', toString(number % 40)), concat('Manufacturer ', toString(number % 40)), concat('MPN_', toString(number)),
 if(number % 10 = 0, NULL, toInt64(1042)), if(number % 10 = 0, NULL, 'Capacitors'), [toInt64(1042)],
 if(number < 200, NULL, if(number % 3 = 0, 'EOL', 'Active')), if(number % 10 = 0, NULL, 1.5), ['CN'], [], ['supplier_1'], toDateTime64('2026-04-27 00:00:00', 3, 'UTC')
 FROM numbers(3000);

INSERT INTO metric_group_ots_component_market_availability (tenantId, entityId, version, effectiveAt, insertedAt, market_stock_total, market_stock_p50, market_lead_time_p50_days, market_stock_total_warnings, market_stock_p50_warnings, market_lead_time_p50_days_warnings) SETTINGS optimize_on_insert = 0
 SELECT 'acme', concat('cmp_', toString(entity)), version, toDateTime64('2026-04-27 00:00:00', 3, 'UTC') + toIntervalWeek(week),
 toDateTime64('2026-04-27 00:00:00', 3, 'UTC') + toIntervalWeek(week) + toIntervalSecond(duplicate + 1), metric, metric, metric, if(if(duplicate = 0, seq, intDiv(seq, 10)) % 20 = 0, ['fixture_warning'], []), if(if(duplicate = 0, seq, intDiv(seq, 10)) % 20 = 0, ['fixture_warning'], []), if(if(duplicate = 0, seq, intDiv(seq, 10)) % 20 = 0, ['fixture_warning'], [])
 FROM (SELECT entity, week, version, seq, duplicate, ((entity * 1664525 + version * 1013904223 + week * 69069 + 1916663206) % 100000) / 100.0 + duplicate * 1000 AS metric
 FROM (SELECT entity, week, version, row_number() OVER (ORDER BY entity, version, week) - 1 AS seq
 FROM (SELECT number AS entity, arrayJoin(range(26)) AS week FROM numbers(2000))
 ARRAY JOIN range(1, toUInt32(entity % 4 + 2)) AS version)
 ARRAY JOIN if(seq % 10 = 0, [0, 1], [0]) AS duplicate);

